// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    // Fuzz the caller address (actor). The rule: for any caller, if airDrop succeeds, tokenBalance(caller) == old + 20.
    function testFuzz_property(address actor) public {
        // keep actor non-zero to be a valid address
        vm.assume(actor != address(0));

        // Ensure actor has no prior balance as per hasNoBalance modifier requirement
        // We need to ensure tokenBalance[actor] == 0 before call. The contract's hasNoBalance requires that.
        // Because tokenBalance is 0 for all addresses initially, no extra setup needed.

        // Call airDrop as actor and capture whether it succeeded
        bool ok;
        uint256 before = c.tokenBalance(actor);
        vm.prank(actor);
        try c.airDrop() {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 after = c.tokenBalance(actor);

        // If the call succeeded, then in the reference implementation the balance must have increased by exactly 20
        // Single assertion that the reference contract always satisfies: ok ==> after == before + 20
        assertTrue(!ok || after == before + 20);
    }
}

