pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: actor is the caller whose tokenBalance should be zero; helperIsBank controls using the Bank helper
    function testFuzz_property(address actor, bool useHelper) public {
        // keep actor non-zero address to be realistic
        vm.assume(actor != address(0));

        // Ensure actor currently has zero balance in the contract mapping
        // We cannot set internal mapping directly; but ensure the actor hasn't called before by not interacting
        // The property requires actor to have zero balance; restrict to that admissible domain
        // If the actor already has non-zero (rare for freshly deployed c), skip such fuzz inputs
        vm.prank(actor);
        uint256 before = c.tokenBalance(actor);
        vm.assume(before == 0);

        // The contract expects msg.sender to be a Bank-like contract that returns keccak256("Nu Token")
        // If we use a helper, deploy a minimal Bank that reports supportsToken correctly and call through it.
        if (useHelper) {
            BankHelper b = new BankHelper();
            // call airDrop with msg.sender = address(b)
            // need to have b call c.airDrop so msg.sender in c is b
            b.callAirDrop(address(c));
        } else {
            // Directly have the actor be the Bank contract by deploying a BankHelper and impersonating it
            BankHelper b = new BankHelper();
            // make the actor address the caller by using vm.prank
            vm.prank(address(b));
            // call airDrop
            try c.airDrop() {
                // noop
            } catch {
                // noop
            }
        }

        // Exactly one assertion reading c: after successful call the tokenBalance should equal before + 20.
        // We must allow for the possibility the call reverted; in the reference contract with the preconditions met, it should succeed and set +20.
        // Check the final balance of the actor (as seen via the public getter).
        uint256 after = c.tokenBalance(actor);
        // The required single assertion: reference always ensures after == before + 20 for all admissible inputs; mutant violates for some
        assertTrue(after == before + 20);
    }
}

// Minimal helper that behaves as a Bank returning supportsToken and can call airDrop on C
contract BankHelper {
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
    function callAirDrop(address caddr) external {
        C(caddr).airDrop();
    }
}

