pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: caller who will call airDrop, and an unrelated key that may have pre-existing balance
    function testFuzz_property(address caller, address other) public {
        // keep addresses non-zero and distinct to be in wide admissible domain
        caller = bound(caller, address(1), address(type(uint160).max));
        other = bound(other, address(1), address(type(uint160).max));
        vm.assume(caller != other);

        // Arrange: give `other` a non-zero pre-existing balance by directly calling airDrop from that address
        // other must satisfy supportsToken() check by being a Bank-like contract; we deploy a helper bank per caller
        BankHelper bankForCaller = new BankHelper();
        BankHelper bankForOther = new BankHelper();

        // fund and set up `other` by having other be a contract that calls airDrop on c via its fallback
        OtherActor deployerOther = new OtherActor(c, address(bankForOther));
        // make sure deployerOther's tokenBalance is zero initially (it is), then call airDrop to set other balance to +20
        // use prank from deployerOther to be msg.sender inside call
        vm.prank(address(deployerOther));
        deployerOther.doAirDrop();

        // confirm pre balances
        uint256 beforeOther = c.tokenBalance(address(deployerOther));
        // assume other has non-zero balance to be in the admissible domain
        vm.assume(beforeOther != 0);

        // Now perform the primary action: have `caller` call airDrop through a BankHelper that reports supportsToken
        // Deploy an actor that will call through
        CallerActor deployerCaller = new CallerActor(c, address(bankForCaller));
        // perform the call as caller
        vm.prank(address(deployerCaller));
        deployerCaller.doAirDrop();

        // Single assertion: in the reference implementation, no other account's balance decreases after another caller's successful airDrop
        uint256 afterOther = c.tokenBalance(address(deployerOther));
        assertTrue(afterOther >= beforeOther);
    }
}

// Helper that returns the expected supportsToken bytes32
contract BankHelper {
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
}

// Minimal actor contract that calls airDrop on C; its address will be used as msg.sender in c
contract CallerActor {
    C immutable c;
    address immutable bank;
    constructor(C _c, address _bank) {
        c = _c;
        bank = _bank;
    }
    function doAirDrop() external {
        // set msg.sender to this contract when calling c by having an external account call this function in the test via vm.prank
        c.airDrop();
    }

    // emulate Bank behavior when c checks supportsToken() on msg.sender (c will call Bank(msg.sender).supportsToken())
    // The test routes c's external call by having c read supportsToken() from this contract's fallback — implement supportsToken
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
}

// Another actor used to seed a non-zero balance for an unrelated account
contract OtherActor {
    C immutable c;
    address immutable bank;
    constructor(C _c, address _bank) {
        c = _c;
        bank = _bank;
    }
    function doAirDrop() external {
        c.airDrop();
    }
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: actor (the caller that will invoke airDrop) and some other address keyK
    function testFuzz_property(address actor, address keyK) public {
        // keep addresses in sane non-zero range
        vm.assume(actor != address(0));
        vm.assume(keyK != address(0));

        // Ensure actor meets hasNoBalance precondition: tokenBalance[actor] == 0
        // We cannot directly set storage in c, so ensure by not calling anything as actor beforehand.

        // We need msg.sender of airDrop to be a contract that responds to supportsToken() with keccak256("Nu Token").
        // Deploy a minimal helper that advertises support and forwards calls to c by calling c.airDrop from itself.
        TokenSupporter supporter = new TokenSupporter();

        // Make sure the supporter has no prior interactions with c (its tokenBalance should be 0)
        // Now have the supporter call c.airDrop but with tx.origin = actor, so msg.sender inside airDrop is supporter.
        // To make actor be the effective caller for tokenBalance indexing, we will have supporter perform an external call
        // that sets msg.sender for the mapping index by using the actor to call supporter which then calls c.airDrop.

        // Fund actor so they can send a call transaction to supporter
        vm.deal(actor, 1 ether);

        // Actor calls supporter which will call c.airDrop() (so msg.sender inside C is supporter)
        vm.prank(actor);
        supporter.callAirDrop(address(c));

        // At this point supporter invoked airDrop; however tokenBalance mapping keys are indexed by msg.sender inside airDrop.
        // In the reference contract, supportsToken checks Bank(msg.sender).supportsToken(), i.e., supporter must implement supportsToken.
        // Our TokenSupporter implements supportsToken() to return keccak256("Nu Token").

        // Record balances for all relevant keys: actor and keyK
        uint before_actor = c.tokenBalance(actor);
        uint before_keyK = c.tokenBalance(keyK);

        // Now perform the same call again from actor -> supporter -> c.airDrop to exercise the non-decreasing check
        vm.prank(actor);
        supporter.callAirDrop(address(c));

        // Record after balances
        uint after_actor = c.tokenBalance(actor);
        uint after_keyK = c.tokenBalance(keyK);

        // The general invariant we assert: for the reference, calling airDrop when preconditions hold
        // never changes any other account's balance; only the caller's balance increases by exactly 20.
        // We assert that keyK's balance is unchanged. This holds for the reference for all inputs, but the mutant can make some other key decrease.
        assertTrue(after_keyK == before_keyK);
    }
}

// Helper contract that advertises support for the token and forwards the airDrop call to target C
contract TokenSupporter {
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
    function callAirDrop(address target) external {
        C(target).airDrop();
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: attackerAddressSeed picks the attacker identity, victimSeed picks a victim address to observe
    function testFuzz_property(uint256 attackerSeed, uint256 victimSeed) public {
        // keep addresses within wide domain but non-zero
        address attacker = address(uint160(uint256(keccak256(abi.encodePacked(attackerSeed)))));
        address victim = address(uint160(uint256(keccak256(abi.encodePacked(victimSeed)))));
        vm.assume(attacker != address(0));
        vm.assume(victim != address(0));

        // Deploy a reentrant attacker that will call back into c.airDrop during airDrop execution
        ReentrantAttacker ra = new ReentrantAttacker(c);
        // fund attacker so it can be msg.sender when c.supportsToken() is called (Bank(msg.sender))
        vm.deal(address(ra), 1 ether);

        // Ensure attacker has no existing token balance and victim has no balance initially
        // attacker will be the msg.sender that calls airDrop via the contract itself
        // First, make sure both have zero balances from c getters
        // (they should be zero on fresh contract, but keep assumptions wide)
        assert(c.tokenBalance(address(0)) >= 0);

        // The attacker contract will act as the Bank: its supportsToken returns keccak256("Nu Token")
        // We need to trigger airDrop from the attacker contract so that supportsToken() check passes
        // Before the call, record victim balance
        uint256 beforeVictim = c.tokenBalance(victim);

        // Now perform the attack: have the attacker contract call airDrop.
        // The attacker will, during its handling of supportsToken() or via fallback, attempt reentrancy
        // Use vm.prank to have the call originate from the attacker contract address
        vm.prank(address(ra));
        // call airDrop() externally from attacker contract by invoking a helper which calls c.airDrop()
        // The attacker contract's internal behavior will try to reenter c.airDrop and modify victim balance
        ra.callAirDrop();

        // After call completes, read victim's balance. In the correct contract this should be unchanged from before.
        uint256 afterVictim = c.tokenBalance(victim);

        // The universal property: for all inputs attackerSeed,victimSeed the reference contract keeps victim's balance unchanged
        // The mutant (that disables _locked=true) will permit a reentrant attacker to change victim's balance for some inputs
        assertTrue(afterVictim == beforeVictim);
    }
}

// Minimal re-entrant attacker: acts as Bank (supportsToken) and during call sequence will reenter c.airDrop
contract ReentrantAttacker {
    C public target;
    bool public reentered = false;

    constructor(C _target) {
        target = _target;
    }

    // The Bank interface: returns keccak256("Nu Token") to satisfy supportsToken modifier
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }

    // Called by the test to initiate the sequence from this contract's address
    function callAirDrop() external {
        // This contract calls target.airDrop(); during execution, because target will call Bank(msg.sender).supportsToken(),
        // that call goes to this contract (supportsToken). We use the opportunity: in supportsToken nothing can reenter,
        // but after supportsToken returns, the target will continue and update tokenBalance[msg.sender].
        // To create a reentrancy window we will, before calling target.airDrop, set up state so that a fallback
        // or external call from target could reenter — however target does not call external functions except supportsToken.
        // To force reentrancy we directly call target.airDrop here, and then in a separate step attempt reentrancy by
        // calling target.airDrop again from within a low-level call that the target may perform (not available).
        // Simpler reliable approach: during the first call we call target.airDrop(), and from this contract we will attempt
        // to reenter by invoking target.airDrop in a different call path triggered by executing target.airDrop's own
        // external interactions; since target only calls supportsToken() on this contract, and that is within our control,
        // we perform the reentrant call from supportsToken via using a state machine: the first time supportsToken is invoked
        // we trigger a nested call back into target.airDrop.
        reentered = false;
        target.airDrop();
    }

    // We override supportsToken to perform reentry on its first invocation
    function supportsTokenWithReentry() external returns (bytes32) {
        if (!reentered) {
            reentered = true;
            // Attempt to reenter target.airDrop(); this will be reentrant if target does not properly lock
            // We ignore failures to let the outer call proceed
            try target.airDrop() {
            } catch {}
        }
        return keccak256(abi.encodePacked("Nu Token"));
    }

    // Make supportsToken() externally visible and route to supportsTokenWithReentry to allow stateful behavior
    function supportsToken() external returns (bytes32) {
        return supportsTokenWithReentry();
    }
}
